style.css:
@-moz-document domain("roblox.com") {
/* Base background */
  body, html {
    background-color: #1a001f !important;
    color: #e0b3ff !important;
    font-family: 'Segoe UI', 'Roboto', sans-serif !important;
    background-image: url("https://i.imgur.com/W4F0ZXO.jpeg"); /* Danganronpa art */
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
    background-position: center;
  }

  /* Navigation Bar */
  .navigation-container, .navbar, header {
    background-color: rgba(26, 0, 31, 0.9) !important;
    border-bottom: 2px solid #cc00ff !important;
  }

  /* Cards / Sections */
  .section, .game-card, .card, .container, .games-list, .game-tile {
    background-color: rgba(0, 0, 0, 0.65) !important;
    border-radius: 10px !important;
    box-shadow: 0 0 10px #9900cc !important;
    color: #f0d9ff !important;
  }

  /* Buttons & Inputs */
  button, input, select, textarea {
    background-color: #330033 !important;
    color: #fff !important;
    border: 1px solid #ff4dd2 !important;
  }

  button:hover {
    background-color: #4d004d !important;
  }

  /* Links */
  a {
    color: #ff66cc !important;
  }

  a:hover {
    color: #ff99ff !important;
    text-shadow: 0 0 5px #ffb3ff;
  }

  /* Selection highlight */
  ::selection {
    background: #ff33cc;
    color: #fff;
  }

  /* Remove white flashes on some Roblox areas */
  .light-theme, .theme-light {
    background-color: transparent !important;
  }

  /* Hide annoying promo banners (optional) */
  .promo-banner, .advertisement, .sponsorship {
    display: none !important;
  }
}
